            if (grid[i][j] == '@') {
                oilDeposits.add(i + "-" + j);
            }

            // If the current cell is not an oil pocket, check if it is adjacent to an oil pocket
            else if (grid[i][j] != '*') {
                // Check if the current cell is adjacent to the top of the grid
