public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2 || start.length != 2 || paths.length != 2) {
        return "cannot be travelled";
    }

    int[][] visited = new int[n][n];
    Queue<int[]> queue = new LinkedList<>();

    queue.offer(start);
    visited[start[0]][start[1]] = 1;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        for (int[] path : paths) {
            if (current[0] + path[0] >= n || current[1] + path[1] >= n || current[0] + path[0] < 0 || current[1] + path[1] < 0) {
                continue;
            }
            int[] next = new int[2];
            next[0] = current[0] + path[0];
            next[1] = current[1] + path[1];
            if (visited[next[0]][next[1]] == 1 || next[0] == end[0] && next[1] == end[1]) {
                return "can be travelled";
            }
            if (visited[next[0]][next[1]] == 0) {
                queue.offer(next);
                visited[next[0]][next[1]] = 1;
            }
        }
    }
    return "cannot be travelled";
}

