public double trimMean(int[] arr) {
    // Find the smallest 5% and largest 5% of elements
    int n = arr.length;
    int minIndex = Math.round(n * 0.05);
    int maxIndex = n - Math.round(n * 0.05) - 1;
    int[] trimmedArr = new int[n - minIndex - maxIndex];
    System.arraycopy(arr, minIndex, trimmedArr, 0, trimmedArr.length);
    System.arraycopy(arr, maxIndex, trimmedArr, trimmedArr.length, n - maxIndex);

    // Calculate the mean of the trimmed array
    int sum = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        sum += trimmedArr[i];
    }
    return (double)sum / (trimmedArr.length - 2);
}

